// DeployAutonity deploys a new Ethereum contract, binding an instance of Autonity to it.
func (r *Runner) DeployAutonity(opts *runOptions, _validators []IAutonityValidator, _config IAutonityConfig) (common.Address, uint64, *Autonity, error) {
	parsed, err := AutonityMetaData.GetAbi()
	if err != nil {
		return common.Address{}, 0, nil, err
	}
	if parsed == nil {
		return common.Address{}, 0, nil, errors.New("GetABI returned nil")
	}

	address, gasConsumed, c, data, err := r.deployContract(opts, parsed, common.FromHex(AutonityBin), _validators, _config)
	if err != nil {
		return common.Address{}, 0, nil, (&Autonity{contract: c}).DecodeError(data, err)
	}
	return address, gasConsumed, &Autonity{contract: c}, nil
}

